import React, { useState, useEffect } from 'react';
import { Eye, Download, X } from 'lucide-react';

// ─── PDF template base64 (PSLS SE2026 blank) ─────────────────────
const PSLS_PDF_B64 = "";

// ─── Koordinat tiap field (PDF points, origin bottom-left) ───────
// PDF size: 841.92 x 595.32 pt (A4 landscape)
const FIELDS = {
  // Header info
  provinsi:   { x:  63, y: 517.9 },
  kabupaten:  { x:  63, y: 510.0 },
  kecamatan:  { x:  63, y: 502.8 },
  desa:       { x:  63, y: 495.6 },
  // Tabel SEBELUM – baris 1
  prov1:      { x:  19.4, y: 437 },
  kab1:       { x:  30.2, y: 437 },
  kec1:       { x:  41.8, y: 437 },
  desa1:      { x:  52.9, y: 437 },
  kdsls1:     { x:  67.0, y: 437 },
  subsls1:    { x:  83.1, y: 437 },
  nmsls1:     { x: 120.6, y: 437 },
  // Tabel SETELAH – baris 1
  prov2:      { x: 207.0, y: 437 },
  kab2:       { x: 218.8, y: 437 },
  kec2:       { x: 231.4, y: 437 },
  desa2:      { x: 244.0, y: 437 },
  nmdesa2:    { x: 268.2, y: 437 },
  kdsls2:     { x: 299.1, y: 437 },
  subsls2:    { x: 315.0, y: 437 },
  nmsls2:     { x: 592.1, y: 437 },
  ketua:      { x: 676.7, y: 437 },
  status:     { x: 730.0, y: 437 },
  batas:      { x: 776.0, y: 437 },
  // Keterangan pengisi
  nmPetugas:  { x: 374.3, y:  68.0 },
  nmPemeriksa:{ x: 593.9, y:  68.0 },
  tglPetugas: { x: 390.5, y:  51.8 },
  tglPemeriksa:{ x: 610.1, y:  51.8 },
};

function parseIdSubsls(idsubsls = '') {
  const s = String(idsubsls).padStart(16, '0');
  return {
    kdprov:   s.slice(0, 2),
    kdkab:    s.slice(2, 4),
    kdkec:    s.slice(4, 7),
    kddesa:   s.slice(7, 10),
    kdsls:    s.slice(10, 14),
    kdsubsls: s.slice(14, 16),
  };
}

export default function PslsPreviewModal({ data, onClose, onConfirm }) {
  const [pdfUrl, setPdfUrl]     = useState(null);
  const [loading, setLoading]   = useState(true);
  const [pdfBytes, setPdfBytes] = useState(null);
  const [error, setError]       = useState(null);

  const {
    props,
    changeTypeParsed,
    adaPerubahanBatas,
    adaPerubahanNama,
    nmslsBaru,
    ketuaSls,
    pplName,
    pmlName,
  } = data;

  const tanggal  = new Date().toLocaleDateString('id-ID', { day: 'numeric', month: 'long', year: 'numeric' });
  const parsed   = parseIdSubsls(props.idsubsls);
  const nmslsSetelah = adaPerubahanNama === 'ya' ? nmslsBaru : (props.nmsls || '');

  useEffect(() => {
    generatePdf();
  }, []); // eslint-disable-line

  const generatePdf = async () => {
    setLoading(true);
    setError(null);
    try {
      // Load pdf-lib dari CDN
      if (!window.PDFLib) {
        await new Promise((resolve, reject) => {
          const script = document.createElement('script');
          script.src = 'https://cdnjs.cloudflare.com/ajax/libs/pdf-lib/1.17.1/pdf-lib.min.js';
          script.onload  = resolve;
          script.onerror = reject;
          document.head.appendChild(script);
        });
      }
      const { PDFDocument, rgb, StandardFonts } = window.PDFLib;

      // Decode base64 → ArrayBuffer
      const bin = atob(PSLS_PDF_B64);
      const buf = new Uint8Array(bin.length);
      for (let i = 0; i < bin.length; i++) buf[i] = bin.charCodeAt(i);

      const pdfDoc = await PDFDocument.load(buf);
      const page   = pdfDoc.getPages()[0];
      const font   = await pdfDoc.embedFont(StandardFonts.Helvetica);
      const fontB  = await pdfDoc.embedFont(StandardFonts.HelveticaBold);

      const draw = (field, text, bold = false, size = 7) => {
        if (!text) return;
        page.drawText(String(text), {
          x: FIELDS[field].x,
          y: FIELDS[field].y,
          size,
          font: bold ? fontB : font,
          color: rgb(0, 0, 0),
        });
      };

      // Header
      draw('provinsi',  props.nmprov || 'SULAWESI SELATAN', true, 8);
      draw('kabupaten', props.nmkab  || 'BARRU',            true, 8);
      draw('kecamatan', props.nmkec  || '',                 true, 8);
      draw('desa',      props.nmdesa || '',                 true, 8);

      // Tabel SEBELUM
      draw('prov1',   parsed.kdprov,   true);
      draw('kab1',    parsed.kdkab,    true);
      draw('kec1',    parsed.kdkec,    true);
      draw('desa1',   parsed.kddesa,   true);
      draw('kdsls1',  parsed.kdsls,    true);
      draw('subsls1', parsed.kdsubsls, true);
      draw('nmsls1',  props.nmsls || '', false);

      // Tabel SETELAH
      draw('prov2',   parsed.kdprov,   true);
      draw('kab2',    parsed.kdkab,    true);
      draw('kec2',    parsed.kdkec,    true);
      draw('desa2',   parsed.kddesa,   true);
      draw('nmdesa2', props.nmdesa || '', false);
      draw('kdsls2',  parsed.kdsls,    true);
      draw('subsls2', parsed.kdsubsls, true);
      draw('nmsls2',  nmslsSetelah,    false);
      draw('ketua',   ketuaSls || '',  false);
      draw('status',  changeTypeParsed.code, true);
      draw('batas',   adaPerubahanBatas === 'ya' ? '1' : '2', true);

      // Keterangan pengisi
      draw('nmPetugas',   pplName || '', false, 8);
      draw('nmPemeriksa', pmlName || '', false, 8);
      draw('tglPetugas',  tanggal,       false, 7);
      draw('tglPemeriksa',tanggal,       false, 7);

      const bytes = await pdfDoc.save();
      setPdfBytes(bytes);
      const blob = new Blob([bytes], { type: 'application/pdf' });
      setPdfUrl(URL.createObjectURL(blob));
    } catch (err) {
      console.error('PDF generate error:', err);
      setError('Gagal membuat preview PDF: ' + err.message);
    } finally {
      setLoading(false);
    }
  };

  const handleDownload = () => {
    if (!pdfBytes) return;
    const blob = new Blob([pdfBytes], { type: 'application/pdf' });
    const url  = URL.createObjectURL(blob);
    const a    = document.createElement('a');
    a.href     = url;
    a.download = `PSLS_${(props.nmkab||'BARRU').replace(/\s+/g,'_')}_${(props.nmdesa||'').replace(/\s+/g,'_')}_${props.idsubsls||''}.pdf`;
    a.click();
    URL.revokeObjectURL(url);
  };

  return (
    <div style={s.overlay} onClick={onClose}>
      <div style={s.modal} onClick={(e) => e.stopPropagation()}>
        {/* Header */}
        <div style={s.header}>
          <div style={s.headerLeft}>
            <Eye size={18} color="#ff6600" />
            <span style={s.title}>Preview PSLS SE2026</span>
            <span style={s.subtitle}>{props.nmsls}</span>
          </div>
          <button style={s.iconBtn} onClick={onClose}><X size={16} /></button>
        </div>

        {/* Body */}
        <div style={s.body}>
          {loading ? (
            <div style={s.loadingBox}>
              <div style={s.spinner} />
              <span style={s.loadingText}>Membuat preview PDF...</span>
            </div>
          ) : error ? (
            <div style={s.errorBox}>{error}</div>
          ) : (
            <iframe
              src={pdfUrl}
              style={s.iframe}
              title="Preview PSLS"
            />
          )}
        </div>

        {/* Footer */}
        <div style={s.footer}>
          <span style={s.footerNote}>Periksa data sebelum mengirim laporan</span>
          <div style={{ display: 'flex', gap: '10px' }}>
            <button style={s.btnSecondary} onClick={onClose}>Batal</button>
            <button style={s.btnDownload}  onClick={handleDownload} disabled={loading || !!error}>
              <Download size={14} style={{ marginRight: 6 }} /> Download PDF
            </button>
            <button style={s.btnPrimary}   onClick={onConfirm} disabled={loading || !!error}>
              Kirim Laporan
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

const s = {
  overlay:     { position:'fixed', inset:0, backgroundColor:'rgba(0,0,0,0.6)', backdropFilter:'blur(8px)', display:'flex', alignItems:'center', justifyContent:'center', zIndex:9999, padding:'16px' },
  modal:       { background:'#fff', borderRadius:'16px', width:'95vw', maxWidth:'1200px', height:'88vh', display:'flex', flexDirection:'column', overflow:'hidden', boxShadow:'0 24px 80px rgba(0,0,0,0.4)' },
  header:      { display:'flex', justifyContent:'space-between', alignItems:'center', padding:'14px 20px', borderBottom:'1px solid #e5e7eb', background:'#f9fafb', flexShrink:0 },
  headerLeft:  { display:'flex', alignItems:'center', gap:'10px' },
  title:       { fontSize:'15px', fontWeight:700, color:'#111827' },
  subtitle:    { fontSize:'12px', color:'#6b7280', fontStyle:'italic' },
  iconBtn:     { background:'none', border:'1px solid #d1d5db', borderRadius:'8px', cursor:'pointer', padding:'6px', color:'#6b7280', display:'flex', alignItems:'center' },
  body:        { flex:1, overflow:'hidden', background:'#f3f4f6', display:'flex', alignItems:'center', justifyContent:'center' },
  iframe:      { width:'100%', height:'100%', border:'none' },
  loadingBox:  { display:'flex', flexDirection:'column', alignItems:'center', gap:'14px' },
  spinner:     { width:'36px', height:'36px', border:'3px solid #e5e7eb', borderTop:'3px solid #ff6600', borderRadius:'50%', animation:'spin 0.8s linear infinite' },
  loadingText: { fontSize:'14px', color:'#6b7280' },
  errorBox:    { padding:'20px', color:'#dc2626', fontSize:'13px', textAlign:'center' },
  footer:      { display:'flex', justifyContent:'space-between', alignItems:'center', padding:'12px 20px', borderTop:'1px solid #e5e7eb', background:'#f9fafb', flexShrink:0, gap:'12px', flexWrap:'wrap' },
  footerNote:  { fontSize:'12px', color:'#6b7280' },
  btnSecondary:{ padding:'8px 18px', borderRadius:'8px', background:'none', border:'1px solid #d1d5db', cursor:'pointer', fontSize:'13px', color:'#374151', fontWeight:500 },
  btnDownload: { display:'flex', alignItems:'center', padding:'8px 16px', borderRadius:'8px', background:'#374151', color:'#fff', border:'none', cursor:'pointer', fontSize:'13px', fontWeight:600 },
  btnPrimary:  { padding:'8px 20px', borderRadius:'8px', background:'#ff6600', border:'none', cursor:'pointer', fontSize:'13px', color:'#fff', fontWeight:600 },
};